mapper.select:
SELECT id, space_id, event_id, accepting_applications
FROM forms
WHERE space_id = #{spaceId} AND event_id = #{eventId}

SELECT id, space_id, event_id, accepting_applications
FROM forms
WHERE id = #{formId} AND space_id = #{spaceId} AND event_id = #{eventId}

SELECT count(*)
FROM forms
WHERE space_id = #{spaceId} AND event_id = #{eventId}

SELECT id AS form_id, accepting_applications
FROM forms
WHERE space_id = #{spaceId} AND event_id = #{eventId}

SELECT id AS field_id, kind, system_key, label, position
FROM fields
WHERE space_id = #{spaceId} AND event_id = #{eventId} AND form_id = #{formId}
ORDER BY ${orderByClause}

SELECT id AS field_id, kind, system_key, label, position
FROM fields
WHERE id = #{fieldId}
  AND form_id = #{formId}
  AND space_id = #{spaceId}
  AND event_id = #{eventId}

SELECT count(*)
FROM fields
WHERE space_id = #{spaceId}
  AND event_id = #{eventId}
  AND form_id = #{formId}
  AND kind = 'CUSTOM'

SELECT COALESCE(MAX(position), -1)
FROM fields
WHERE space_id = #{spaceId} AND event_id = #{eventId} AND form_id = #{formId}
